insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'barbell-bench-press', 'Bench press s velkou činkou', 'Barbell bench press', 'push', array['chest']::text[], array['triceps','front_delts']::text[], array['barbell','bench']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Lopatky stažené k sobě a dolů, chodidla pevně na zemi, předloktí kolmo k zemi."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Shoulder blades pinned back and down, feet planted, forearms vertical."]}'::jsonb, '{"cs":["Odrážení činky od hrudníku"],"en":["Bouncing the bar off the chest"]}'::jsonb, array['dumbbell-bench-press','push-up']::text[], array['paused-bench-press']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'paused-bench-press', 'Bench press s pauzou', 'Paused bench press', 'push', array['chest']::text[], array['triceps','front_delts']::text[], array['barbell','bench']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Činku zastav na hrudníku na 1–2 s, pak dynamicky vytlač."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Pause the bar on the chest for 1–2 s, then press explosively."]}'::jsonb, '{"cs":["Uvolnění napětí během pauzy"],"en":["Losing tension during the pause"]}'::jsonb, array['barbell-bench-press']::text[], array[]::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'incline-barbell-bench-press', 'Šikmý bench press s velkou činkou', 'Incline barbell bench press', 'push', array['chest','front_delts']::text[], array['triceps']::text[], array['barbell','bench']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Lavice 30–45°, činka klesá k horní části hrudníku."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Bench at 30–45°, lower the bar to the upper chest."]}'::jsonb, '{"cs":["Lokty roztažené do 90° — zátěž na ramena"],"en":["Elbows flared to 90° — stresses the shoulders"]}'::jsonb, array['incline-dumbbell-press']::text[], array[]::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'decline-bench-press', 'Bench press hlavou dolů', 'Decline bench press', 'push', array['chest']::text[], array['triceps']::text[], array['barbell','bench']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Lopatky stažené k sobě a dolů, chodidla pevně na zemi, předloktí kolmo k zemi."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Shoulder blades pinned back and down, feet planted, forearms vertical."]}'::jsonb, '{"cs":["Příliš strmý úhel lavice"],"en":["Bench angle too steep"]}'::jsonb, array['dips-assisted']::text[], array[]::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'close-grip-bench-press', 'Bench press úzkým úchopem', 'Close-grip bench press', 'push', array['triceps','chest']::text[], array['front_delts']::text[], array['barbell','bench']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Úchop na šíři ramen, lokty podél těla."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Shoulder-width grip, elbows tucked."]}'::jsonb, '{"cs":["Příliš úzký úchop zatěžující zápěstí"],"en":["Grip too narrow, straining the wrists"]}'::jsonb, array['diamond-push-up']::text[], array[]::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'dumbbell-bench-press', 'Tlak s jednoručkami na lavici', 'Dumbbell bench press', 'push', array['chest']::text[], array['triceps','front_delts']::text[], array['dumbbell','bench']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Lopatky stažené k sobě a dolů, chodidla pevně na zemi, předloktí kolmo k zemi."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Shoulder blades pinned back and down, feet planted, forearms vertical."]}'::jsonb, '{"cs":["Lokty roztažené do 90° — zátěž na ramena"],"en":["Elbows flared to 90° — stresses the shoulders"]}'::jsonb, array['push-up']::text[], array['barbell-bench-press']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'incline-dumbbell-press', 'Tlak s jednoručkami na šikmé lavici', 'Incline dumbbell press', 'push', array['chest','front_delts']::text[], array['triceps']::text[], array['dumbbell','bench']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Lavice 30°, jednoručky klesají ke straně hrudníku."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Bench at 30°, lower dumbbells beside the upper chest."]}'::jsonb, '{"cs":["Lokty roztažené do 90° — zátěž na ramena"],"en":["Elbows flared to 90° — stresses the shoulders"]}'::jsonb, array['push-up']::text[], array['incline-barbell-bench-press']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'dumbbell-fly', 'Rozpažování s jednoručkami', 'Dumbbell fly', 'push', array['chest']::text[], array['front_delts']::text[], array['dumbbell','bench']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Mírně pokrčené lokty, pohyb jako objímání stromu."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Soft elbows, move as if hugging a tree."]}'::jsonb, '{"cs":["Propnuté lokty a příliš těžká váha"],"en":["Locked elbows and too much weight"]}'::jsonb, array['cable-fly']::text[], array[]::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'cable-fly', 'Rozpažování na kladkách', 'Cable fly', 'push', array['chest']::text[], array['front_delts']::text[], array['cable']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Krok vpřed, mírný předklon, ruce se setkají před hrudníkem."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Step forward, slight lean, hands meet in front of the chest."]}'::jsonb, '{"cs":["Ohýbání loktů — z rozpažování je tlak"],"en":["Bending elbows so it turns into a press"]}'::jsonb, array['machine-chest-fly']::text[], array['dumbbell-fly']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'machine-chest-press', 'Tlak na hrudník na stroji', 'Machine chest press', 'push', array['chest']::text[], array['triceps','front_delts']::text[], array['machine']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Rukojeti ve výšce středu hrudníku, záda opřená."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Handles at mid-chest height, back against the pad."]}'::jsonb, '{"cs":["Zvedání ramen od opěradla"],"en":["Shoulders lifting off the pad"]}'::jsonb, array[]::text[], array['dumbbell-bench-press']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'machine-chest-fly', 'Butterfly na stroji', 'Machine chest fly (pec deck)', 'push', array['chest']::text[], array['front_delts']::text[], array['machine']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Lokty v rovině ramen, stisk uprostřed na 1 s."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Elbows at shoulder level, squeeze 1 s in the middle."]}'::jsonb, '{"cs":["Zkrácený rozsah pohybu"],"en":["Cutting the range of motion short"]}'::jsonb, array[]::text[], array['cable-fly']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'push-up', 'Klik', 'Push-up', 'push', array['chest']::text[], array['triceps','front_delts','abs']::text[], array['bodyweight']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Tělo jako prkno, lokty asi 45° od těla, hrudník k zemi."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Body in a straight plank, elbows ~45°, chest to the floor."]}'::jsonb, '{"cs":["Propadlá bedra"],"en":["Sagging hips"]}'::jsonb, array['incline-push-up']::text[], array['deficit-push-up','weighted-push-up']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'incline-push-up', 'Klik s rukama na vyvýšení', 'Incline push-up', 'push', array['chest']::text[], array['triceps','front_delts']::text[], array['bodyweight','bench']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Ruce na lavici nebo stole; čím výš, tím snazší."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Hands on a bench or table — the higher, the easier."]}'::jsonb, '{"cs":["Propadlá bedra"],"en":["Sagging hips"]}'::jsonb, array['wall-push-up']::text[], array['push-up']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'wall-push-up', 'Klik o zeď', 'Wall push-up', 'push', array['chest']::text[], array['triceps']::text[], array['bodyweight']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Ruce na zdi ve výšce ramen, tělo rovné."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Hands on the wall at shoulder height, body straight."]}'::jsonb, '{"cs":["Zkrácený rozsah pohybu"],"en":["Cutting the range of motion short"]}'::jsonb, array[]::text[], array['incline-push-up']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'deficit-push-up', 'Klik s prohloubením', 'Deficit push-up', 'push', array['chest']::text[], array['triceps','front_delts']::text[], array['bodyweight']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Ruce na kotoučích, hrudník klesá pod úroveň dlaní."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Hands on plates, chest drops below hand level."]}'::jsonb, '{"cs":["Propadlá bedra"],"en":["Sagging hips"]}'::jsonb, array['push-up']::text[], array['weighted-push-up']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
