insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'diamond-push-up', 'Diamantový klik', 'Diamond push-up', 'push', array['triceps']::text[], array['chest']::text[], array['bodyweight']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Palce a ukazováčky tvoří diamant pod hrudníkem."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Thumbs and index fingers form a diamond under the chest."]}'::jsonb, '{"cs":["Lokty utíkají do stran"],"en":["Elbows flaring out"]}'::jsonb, array['push-up']::text[], array[]::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'dips', 'Kliky na bradlech', 'Parallel bar dips', 'push', array['chest','triceps']::text[], array['front_delts']::text[], array['bodyweight']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Mírný předklon pro hrudník, klesej do 90° v lokti."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Slight forward lean for chest, lower to 90° at the elbow."]}'::jsonb, '{"cs":["Příliš hluboký sestup s bolestí ramen"],"en":["Going too deep with shoulder pain"]}'::jsonb, array['dips-assisted','bench-dip']::text[], array['weighted-dips']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
