insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'overhead-press', 'Tlak nad hlavu s velkou činkou', 'Barbell overhead press', 'push', array['front_delts','side_delts']::text[], array['triceps','upper_back']::text[], array['barbell']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Zpevněný trup a hýždě, tlač nad hlavu a dokonči s hlavou „skrz okno“."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Brace abs and glutes, press overhead and finish with the head “through the window”."]}'::jsonb, '{"cs":["Prohnutá bedra při tlaku nad hlavu"],"en":["Arching the lower back when pressing overhead"]}'::jsonb, array['dumbbell-shoulder-press']::text[], array['push-press']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
