insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'landmine-press', 'Landmine tlak', 'Landmine press', 'push', array['front_delts']::text[], array['chest','triceps','obliques']::text[], array['landmine','barbell']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Tlač šikmo vzhůru, zpevněný trup — šetrné k ramenům."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Press up and forward with a braced trunk — shoulder-friendly."]}'::jsonb, '{"cs":["Rotace trupu"],"en":["Twisting the torso"]}'::jsonb, array['incline-push-up']::text[], array['dumbbell-shoulder-press']::text[], true) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'pike-push-up', 'Klik ve stoji na lopatkách (pike)', 'Pike push-up', 'push', array['front_delts']::text[], array['triceps','upper_back']::text[], array['bodyweight']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Boky vysoko, hlava klesá mezi ruce."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Hips high, head lowers between the hands."]}'::jsonb, '{"cs":["Hlava před rukama"],"en":["Head landing in front of the hands"]}'::jsonb, array['push-up']::text[], array['handstand-push-up']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'handstand-push-up', 'Klik ve stojce', 'Handstand push-up', 'push', array['front_delts','triceps']::text[], array['upper_back','abs']::text[], array['bodyweight']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Stojka u zdi, hlava klesá do trojúhelníku s rukama."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Wall handstand, head lowers into a triangle with the hands."]}'::jsonb, '{"cs":["Prohnutá bedra při tlaku nad hlavu"],"en":["Arching the lower back when pressing overhead"]}'::jsonb, array['pike-push-up']::text[], array[]::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
