insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'pull-up', 'Shyb nadhmatem', 'Pull-up', 'pull', array['lats']::text[], array['biceps','upper_back','forearms']::text[], array['pullup_bar']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Začni stažením lopatek dolů, pak táhni lokty k žebrům."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Start by pulling the shoulder blades down, then drive the elbows to the ribs."]}'::jsonb, '{"cs":["Kopání nohama a poloviční opakování"],"en":["Kicking and half reps"]}'::jsonb, array['band-assisted-pull-up','lat-pulldown']::text[], array['weighted-pull-up']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
