insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'band-assisted-pull-up', 'Shyb s gumou', 'Band-assisted pull-up', 'pull', array['lats']::text[], array['biceps','upper_back']::text[], array['pullup_bar','band']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Guma pod koleny odlehčí váhu; ubírej sílu gumy."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","A band under the knees offsets weight; use lighter bands over time."]}'::jsonb, '{"cs":["Zkrácený rozsah pohybu"],"en":["Cutting the range of motion short"]}'::jsonb, array['negative-pull-up']::text[], array['pull-up']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'negative-pull-up', 'Negativní shyb', 'Negative pull-up', 'pull', array['lats']::text[], array['biceps']::text[], array['pullup_bar','box']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Vyskoč nahoru a spouštěj se 3–5 s."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Jump to the top and lower for 3–5 s."]}'::jsonb, '{"cs":["Rychlý pád dolů"],"en":["Dropping fast"]}'::jsonb, array['inverted-row']::text[], array['band-assisted-pull-up']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'weighted-pull-up', 'Shyb se zátěží', 'Weighted pull-up', 'pull', array['lats']::text[], array['biceps','upper_back']::text[], array['pullup_bar']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Začni stažením lopatek dolů, pak táhni lokty k žebrům."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Start by pulling the shoulder blades down, then drive the elbows to the ribs."]}'::jsonb, '{"cs":["Houpání zátěže"],"en":["Letting the weight swing"]}'::jsonb, array['pull-up']::text[], array[]::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
