insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'dead-hang', 'Vis na hrazdě', 'Dead hang', 'pull', array['forearms']::text[], array['lats']::text[], array['pullup_bar']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Uvolněný vis, aktivní ramena, dýchej."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Relaxed hang, active shoulders, breathe."]}'::jsonb, '{"cs":["Úplně povolená ramena u citlivých kloubů"],"en":["Fully passive shoulders if they are sensitive"]}'::jsonb, array[]::text[], array['pull-up']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'back-squat', 'Dřep s velkou činkou na zádech', 'Barbell back squat', 'legs', array['quads','glutes']::text[], array['adductors','lower_back']::text[], array['barbell']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Chodidla na šíři ramen, kolena ve směru špiček, hrudník nahoře, sed mezi paty."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Feet shoulder-width, knees track over toes, chest up, sit down between the heels."]}'::jsonb, '{"cs":["Padání kolen dovnitř"],"en":["Knees caving in"]}'::jsonb, array['goblet-squat','box-squat']::text[], array['paused-squat']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'front-squat', 'Přední dřep', 'Front squat', 'legs', array['quads']::text[], array['glutes','abs','upper_back']::text[], array['barbell']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Lokty vysoko, trup vzpřímený, činka na předních deltech."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Elbows high, upright torso, bar on the front delts."]}'::jsonb, '{"cs":["Padající lokty"],"en":["Elbows dropping"]}'::jsonb, array['goblet-squat']::text[], array[]::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'paused-squat', 'Dřep s pauzou', 'Paused squat', 'legs', array['quads','glutes']::text[], array['adductors']::text[], array['barbell']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","2 s pauza v dolní pozici bez povolení napětí."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","2 s pause at the bottom without relaxing."]}'::jsonb, '{"cs":["Odrážení z dolní pozice"],"en":["Bouncing out of the bottom"]}'::jsonb, array['back-squat']::text[], array[]::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'box-squat', 'Dřep na bednu', 'Box squat', 'legs', array['quads','glutes']::text[], array['hamstrings']::text[], array['barbell','box']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Sedni se zpět na bednu, krátce zastav, vstaň."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Sit back to the box, pause briefly, stand."]}'::jsonb, '{"cs":["Dosednutí s povolením trupu"],"en":["Plopping onto the box"]}'::jsonb, array['goblet-squat']::text[], array['back-squat']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'goblet-squat', 'Goblet dřep', 'Goblet squat', 'legs', array['quads','glutes']::text[], array['abs','adductors']::text[], array['dumbbell','kettlebell']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Jednoručka u hrudníku, lokty mezi koleny dole."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Dumbbell at the chest, elbows inside the knees at the bottom."]}'::jsonb, '{"cs":["Padání kolen dovnitř"],"en":["Knees caving in"]}'::jsonb, array['bodyweight-squat']::text[], array['front-squat']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'bodyweight-squat', 'Dřep s vlastní vahou', 'Bodyweight squat', 'legs', array['quads','glutes']::text[], array['adductors']::text[], array['bodyweight']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Chodidla na šíři ramen, kolena ve směru špiček, hrudník nahoře, sed mezi paty."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Feet shoulder-width, knees track over toes, chest up, sit down between the heels."]}'::jsonb, '{"cs":["Paty se zvedají ze země"],"en":["Heels lifting"]}'::jsonb, array['box-sit-to-stand']::text[], array['goblet-squat']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'box-sit-to-stand', 'Sed–stoj z lavice', 'Box sit-to-stand', 'legs', array['quads','glutes']::text[], array[]::text[], array['box','bodyweight']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Vstaň z lavice bez pomoci rukou, pomalu se posaď."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Stand up from a bench without hands, sit down slowly."]}'::jsonb, '{"cs":["Dopadnutí na lavici"],"en":["Dropping onto the seat"]}'::jsonb, array[]::text[], array['bodyweight-squat']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
