insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'leg-press', 'Legpress', 'Leg press', 'legs', array['quads','glutes']::text[], array['hamstrings']::text[], array['machine']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Bedra na opěradle, kolena nepropínej nahoře."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Lower back on the pad, don’t lock the knees at the top."]}'::jsonb, '{"cs":["Zvedání pánve dole"],"en":["Pelvis rolling up at the bottom"]}'::jsonb, array[]::text[], array['hack-squat']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
