insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'bulgarian-split-squat', 'Bulharský dřep', 'Bulgarian split squat', 'legs', array['quads','glutes']::text[], array['adductors']::text[], array['dumbbell','bench']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Zadní noha na lavici, svisle dolů, přední pata na zemi."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Rear foot on a bench, drop straight down, front heel down."]}'::jsonb, '{"cs":["Odrážení zadní nohou"],"en":["Pushing off the back leg"]}'::jsonb, array['split-squat']::text[], array[]::text[], true) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
