insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'reverse-lunge', 'Výpad vzad', 'Reverse lunge', 'legs', array['quads','glutes']::text[], array['hamstrings']::text[], array['dumbbell','bodyweight']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Krok vzad, trup vzpřímený — šetrnější ke kolenům."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Step back, upright torso — easier on the knees."]}'::jsonb, '{"cs":["Padání kolen dovnitř"],"en":["Knees caving in"]}'::jsonb, array['split-squat']::text[], array['walking-lunge']::text[], true) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'step-up', 'Výstup na bednu', 'Step-up', 'legs', array['quads','glutes']::text[], array[]::text[], array['box','dumbbell']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Celé chodidlo na bedně, odrazová noha jen pomáhá minimálně."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Whole foot on the box, minimal push from the trailing leg."]}'::jsonb, '{"cs":["Odraz zadní nohou"],"en":["Pushing off the back leg"]}'::jsonb, array[]::text[], array[]::text[], true) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
