insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'box-pistol', 'Dřep na jedné noze na bednu', 'Box pistol', 'legs', array['quads','glutes']::text[], array[]::text[], array['box','bodyweight']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Na jedné noze si sedni na bednu a vstaň."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Sit onto a box on one leg and stand up."]}'::jsonb, '{"cs":["Padání kolen dovnitř"],"en":["Knees caving in"]}'::jsonb, array['split-squat']::text[], array['pistol-squat']::text[], true) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'leg-extension', 'Předkopávání na stroji', 'Leg extension', 'legs', array['quads']::text[], array[]::text[], array['machine']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Osa stroje v úrovni kolene, pauza nahoře."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Machine axis at the knee, pause at the top."]}'::jsonb, '{"cs":["Švihání"],"en":["Swinging the weight"]}'::jsonb, array[]::text[], array[]::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
