insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'deadlift', 'Mrtvý tah', 'Conventional deadlift', 'hinge', array['hamstrings','glutes','lower_back']::text[], array['upper_back','forearms','quads']::text[], array['barbell']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Pohyb z kyčlí, neutrální záda, činka blízko nohou."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Hinge at the hips, neutral spine, keep the weight close to the legs."]}'::jsonb, '{"cs":["Kulatá záda"],"en":["Rounding the back"]}'::jsonb, array['trap-bar-deadlift','kettlebell-deadlift']::text[], array['deficit-deadlift']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'sumo-deadlift', 'Mrtvý tah sumo', 'Sumo deadlift', 'hinge', array['glutes','adductors','quads']::text[], array['hamstrings','lower_back']::text[], array['barbell']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Široký postoj, kolena ven, hrudník nahoru."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Wide stance, knees out, chest up."]}'::jsonb, '{"cs":["Boky vystřelí nahoru dřív než činka"],"en":["Hips shooting up before the bar"]}'::jsonb, array['trap-bar-deadlift']::text[], array[]::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'trap-bar-deadlift', 'Mrtvý tah s trap osou', 'Trap bar deadlift', 'hinge', array['glutes','quads','hamstrings']::text[], array['lower_back','traps']::text[], array['trap_bar']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Stůj uprostřed osy, tlač zem nohama."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Stand inside the bar, push the floor away."]}'::jsonb, '{"cs":["Kulatá záda"],"en":["Rounding the back"]}'::jsonb, array['kettlebell-deadlift']::text[], array['deadlift']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
