insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'hip-hinge-drill', 'Nácvik předklonu s tyčí', 'Dowel hip hinge drill', 'hinge', array['hamstrings','glutes']::text[], array[]::text[], array['bodyweight']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Tyč se dotýká hlavy, hrudníku i kostrče po celou dobu."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Dowel touches head, upper back and tailbone throughout."]}'::jsonb, '{"cs":["Ztráta kontaktu tyče"],"en":["Losing contact with the dowel"]}'::jsonb, array[]::text[], array['kettlebell-deadlift']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'romanian-deadlift', 'Rumunský mrtvý tah', 'Romanian deadlift', 'hinge', array['hamstrings','glutes']::text[], array['lower_back','forearms']::text[], array['barbell','dumbbell']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Mírně pokrčená kolena, boky dozadu do protažení hamstringů."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Soft knees, push the hips back to a hamstring stretch."]}'::jsonb, '{"cs":["Kulatá záda"],"en":["Rounding the back"]}'::jsonb, array['kettlebell-deadlift']::text[], array['single-leg-rdl']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'single-leg-rdl', 'Rumunský mrtvý tah na jedné noze', 'Single-leg Romanian deadlift', 'hinge', array['hamstrings','glutes']::text[], array['abs']::text[], array['dumbbell','kettlebell']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Pánev rovně, zadní noha a trup v jedné linii."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Hips square, rear leg and torso in one line."]}'::jsonb, '{"cs":["Otáčení pánve"],"en":["Hips rotating open"]}'::jsonb, array['romanian-deadlift']::text[], array[]::text[], true) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
