insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'seated-leg-curl', 'Zakopávání vsedě', 'Seated leg curl', 'hinge', array['hamstrings']::text[], array[]::text[], array['machine']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Mírný předklon zvětší protažení hamstringů."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","A slight forward lean increases the hamstring stretch."]}'::jsonb, '{"cs":["Zkrácený rozsah pohybu"],"en":["Cutting the range of motion short"]}'::jsonb, array[]::text[], array[]::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'kettlebell-swing', 'Kettlebell swing', 'Kettlebell swing', 'hinge', array['glutes','hamstrings']::text[], array['lower_back','abs','forearms']::text[], array['kettlebell']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Výbušný hip hinge, ruce jen vedou, nahoře stoj ve „prkně“."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Explosive hip hinge, arms only guide, finish in a standing plank."]}'::jsonb, '{"cs":["Dřep místo švihu a tahání rukama"],"en":["Squatting and lifting with the arms"]}'::jsonb, array['kettlebell-deadlift']::text[], array[]::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
