insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'copenhagen-plank', 'Kodaňské prkno', 'Copenhagen plank', 'core', array['adductors']::text[], array['obliques']::text[], array['bench','bodyweight']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Horní noha na lavici, spodní pod ní, boky nahoře."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Top leg on the bench, bottom leg under it, hips up."]}'::jsonb, '{"cs":["Padání boků"],"en":["Hips dropping"]}'::jsonb, array['side-plank']::text[], array[]::text[], true) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
