insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'power-clean', 'Přemístění (power clean)', 'Power clean', 'olympic', array['glutes','hamstrings','traps']::text[], array['quads','upper_back','calves']::text[], array['barbell']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Tah ze země jako mrtvý tah, výbušná extenze kyčlí, rychlé zachycení na předních deltech."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Pull like a deadlift, explosive hip extension, fast catch on the front delts."]}'::jsonb, '{"cs":["Tahání rukama příliš brzy"],"en":["Pulling with the arms too early"]}'::jsonb, array['hang-power-clean']::text[], array[]::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
