insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'box-jump', 'Skok na bednu', 'Box jump', 'plyometric', array['quads','glutes']::text[], array['calves']::text[], array['box']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Výbušný pohyb, měkké doskoky, maximální kvalita každého opakování."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Explosive intent, soft landings, maximum quality on every rep."]}'::jsonb, '{"cs":["Doskok do hlubokého dřepu"],"en":["Landing in a deep squat"]}'::jsonb, array['squat-jump']::text[], array['depth-jump']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
