insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'shadow-boxing', 'Stínový box', 'Shadow boxing', 'conditioning', array['front_delts','obliques']::text[], array['calves','triceps']::text[], array['bodyweight']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Ruce u brady, rotace z boků, lehké nohy."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Hands up at the chin, rotate from the hips, light feet."]}'::jsonb, '{"cs":["Padající garda"],"en":["Dropping the guard"]}'::jsonb, array[]::text[], array['heavy-bag-rounds']::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'heavy-bag-rounds', 'Kola na pytli', 'Heavy bag rounds', 'conditioning', array['front_delts','obliques']::text[], array['triceps','calves','abs']::text[], array['bodyweight']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Kombinace v sériích, dýchej s údery, zpevněné zápěstí."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Combinations in bursts, exhale on punches, firm wrists."]}'::jsonb, '{"cs":["Údery bez bandáží"],"en":["Hitting without hand wraps"]}'::jsonb, array['shadow-boxing']::text[], array[]::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
