insert into public.exercises (owner_id, slug, name_cs, name_en, category, primary_muscles, secondary_muscles, equipment, instructions, mistakes, regressions, progressions, unilateral) values (null, 'neck-isometrics', 'Izometrie krku', 'Neck isometrics', 'core', array['neck']::text[], array['traps']::text[], array['bodyweight']::text[], '{"cs":["Rozcvič se: 1–2 lehké série s nižší váhou.","Nastav pozici a zpevni trup.","Proveď opakování kontrolovaně v plném rozsahu, který zvládneš bez bolesti.","Dýchej: výdech v nejnáročnější fázi.","Ruka tlačí proti hlavě, krk drží neutrální pozici 10–20 s."],"en":["Warm up with 1–2 lighter sets.","Set up your position and brace your trunk.","Perform controlled reps through the full pain-free range you own.","Breathe out during the hardest part of the rep.","Hand presses against the head, neck holds neutral for 10–20 s."]}'::jsonb, '{"cs":["Příliš velká síla a bolest"],"en":["Pushing too hard into pain"]}'::jsonb, array[]::text[], array[]::text[], false) on conflict (owner_id, slug) do update set name_cs = excluded.name_cs, name_en = excluded.name_en, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, instructions = excluded.instructions, mistakes = excluded.mistakes;
